std::mt19937 engine;

// Method 1: Seeding upon construction
std::mt19937 engine_a(100U);

// Method 2: Calling seed() member function
// This invokes the internal initialization algorithm
// (e.g., fills mt19937's 624-element state array)
engine.seed(42U);

int val_1 = engine();

// Calling seed() resets the engine state
engine.seed(42U);

int val_2 = engine(); // val_2 == val_1 (identical sequence restart)

// Seeding with non-deterministic input
std::random_device rd;
engine.seed(rd()); // Runtime initialization with entropy
